package com.chromascape.web.replay.hash;

import static org.assertj.core.api.Assertions.assertThat;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.core.io.ClassPathResource;

/**
 * SC-275 cross-language parity: reads the byte-identical {@code
 * replay/contracts/sc275-golden-vectors.json} fixture generated by the TypeScript implementation
 * and reproduces every canonical byte, digest, chain frame, and slot view from this Java
 * implementation.
 */
class Sc275GoldenVectorsTest {

  private static final ObjectMapper MAPPER = new ObjectMapper();

  private static JsonNode vectors() throws Exception {
    try (var in =
        new ClassPathResource("replay/contracts/sc275-golden-vectors.json").getInputStream()) {
      return MAPPER.readTree(in);
    }
  }

  @Test
  void vectorMetaPinsV2Versions() throws Exception {
    JsonNode meta = vectors().path("meta");
    assertThat(meta.path("projectionVersion").asInt()).isEqualTo(2);
    assertThat(meta.path("hashVersion").asText()).isEqualTo("sha256-semantic-state-v2");
    assertThat(meta.path("traceVersion").asInt()).isEqualTo(2);
  }

  @Test
  void everyCanonicalCaseReproducesItsBytes() throws Exception {
    for (JsonNode entry : vectors().path("canonicalCases")) {
      assertThat(CausalCanonicalJson.canonicalize(entry.path("input")))
          .as("case %s", entry.path("name").asText())
          .isEqualTo(entry.path("bytes").asText());
    }
  }

  @Test
  void domainAndCompositeHashesReproduce() throws Exception {
    JsonNode root = vectors();
    JsonNode domains = root.path("sampleProjection").path("domains");
    Iterator<Map.Entry<String, JsonNode>> fields = domains.fields();
    while (fields.hasNext()) {
      Map.Entry<String, JsonNode> field = fields.next();
      assertThat(SemanticHashV2.domainHash(field.getKey(), field.getValue()))
          .as("domain %s", field.getKey())
          .isEqualTo(root.path("domainHashes").path(field.getKey()).asText());
    }
    Map<String, String> hashes = new LinkedHashMap<>();
    Iterator<String> names = root.path("domainHashes").fieldNames();
    while (names.hasNext()) {
      String name = names.next();
      hashes.put(name, root.path("domainHashes").path(name).asText());
    }
    long tick = root.path("sampleProjection").path("tick").asLong();
    assertThat(SemanticHashV2.stateHash(tick, hashes))
        .isEqualTo(root.path("sampleStateHash").asText());
  }

  @Test
  void fixedDigestsReproduce() throws Exception {
    JsonNode root = vectors();
    assertThat(SemanticHashV2.nullActionDigest()).isEqualTo(root.path("nullActionDigest").asText());
    assertThat(SemanticHashV2.resultDigest("ACCEPTED", null))
        .isEqualTo(root.path("acceptedResultDigest").asText());
    assertThat(SemanticHashV2.resultDigest("REJECTED", "spot depleted"))
        .isEqualTo(root.path("rejectedResultDigest").asText());
    assertThat(
            SemanticHashV2.runtimeDigest(
                "0.1.0", "c".repeat(40), "sha256:" + "bb".repeat(32), "sha256:" + "cc".repeat(32)))
        .isEqualTo(root.path("runtimeDigest").asText());
    assertThat(
            SemanticHashV2.genesisHash(
                root.path("chainFrames").path(0).path("manifestDigest").asText(),
                root.path("chainFrames").path(0).path("runtimeDigest").asText()))
        .isEqualTo(root.path("genesis").asText());
  }

  @Test
  void vectorChainVerifiesEndToEnd() throws Exception {
    JsonNode root = vectors();
    List<JsonNode> frames = new ArrayList<>();
    root.path("chainFrames").forEach(frames::add);
    JsonNode first = frames.get(0);
    TransitionChainVerifier.VerifyResult result =
        TransitionChainVerifier.verify(
            frames,
            new TransitionChainVerifier.Anchors(
                first.path("manifestDigest").asText(),
                first.path("runtimeDigest").asText(),
                root.path("genesis").asText(),
                frames.get(frames.size() - 1).path("chainHash").asText()));
    assertThat(result.valid()).isTrue();
  }

  @Test
  void vectorSlotViewReproduces() throws Exception {
    JsonNode expected = vectors().path("slotView");
    List<EntitySlotView.SlotEntity> entities =
        List.of(
            new EntitySlotView.SlotEntity("npc:b", 1, 5),
            new EntitySlotView.SlotEntity("npc:a", 1, 2),
            new EntitySlotView.SlotEntity("npc:c", 0, 1));
    EntitySlotView.SlotView rebuilt =
        EntitySlotView.build(
            entities, 2, 3, 11, expected.path("sourceProjectionDigest").asText(), null);
    assertThat(rebuilt.slotMap())
        .containsExactlyElementsOf(toNullableList(expected.path("slotMap")));
    assertThat(rebuilt.viewDigest()).isEqualTo(expected.path("viewDigest").asText());
    assertThat(rebuilt.truncatedCount()).isEqualTo(expected.path("truncatedCount").asInt());
  }

  @Test
  void vectorDiffExampleMatches() throws Exception {
    JsonNode root = vectors();
    StructuralDiff.DiffResult result =
        StructuralDiff.diffValues(
            MAPPER.readTree("{\"stableId\":\"npc:1\",\"secretNote\":\"private\",\"count\":1}"),
            MAPPER.readTree("{\"stableId\":\"npc:2\",\"secretNote\":\"changed\",\"count\":1}"),
            "CAUSAL_STATE",
            "world",
            null,
            null,
            null,
            StructuralDiff.DiffLimits.defaults());
    List<StructuralDiff.StateDifference> diffs = result.differences();
    JsonNode pinnedList = root.path("diffExample").path("differences");
    assertThat(result.truncated())
        .isEqualTo(root.path("diffExample").path("truncated").asBoolean());
    assertThat(diffs).hasSize(pinnedList.size());
    for (int index = 0; index < diffs.size(); index++) {
      JsonNode pinned = pinnedList.path(index);
      assertThat(diffs.get(index).path()).isEqualTo(pinned.path("path").asText());
      assertThat(CausalCanonicalJson.canonicalize(diffs.get(index).expected()))
          .isEqualTo(CausalCanonicalJson.canonicalize(pinned.path("expected")));
      assertThat(CausalCanonicalJson.canonicalize(diffs.get(index).actual()))
          .isEqualTo(CausalCanonicalJson.canonicalize(pinned.path("actual")));
    }
  }

  private static List<String> toNullableList(JsonNode array) {
    List<String> out = new ArrayList<>();
    for (JsonNode entry : array) {
      out.add(entry.isNull() ? null : entry.asText());
    }
    return out;
  }
}
